BEGIN;

ALTER TABLE program ALTER COLUMN name DROP NOT NULL;
ALTER TABLE program ALTER COLUMN code DROP NOT NULL;
ALTER TABLE olympiad ALTER COLUMN host_university_id DROP NOT NULL;
ALTER TABLE olympiad ALTER COLUMN complexity DROP NOT NULL;
ALTER TABLE olympiad ALTER COLUMN description DROP NOT NULL;

TRUNCATE benefit, stage, subject_olympiad, olympiad, subject, programs_universities, program, universities_cities, city, university RESTART IDENTITY CASCADE;




















































SELECT setval(pg_get_serial_sequence('university', 'id'), COALESCE((SELECT MAX(id) FROM university), 1), (SELECT COUNT(*) > 0 FROM university));

SELECT setval(pg_get_serial_sequence('city', 'id'), COALESCE((SELECT MAX(id) FROM city), 1), (SELECT COUNT(*) > 0 FROM city));

SELECT setval(pg_get_serial_sequence('program', 'id'), COALESCE((SELECT MAX(id) FROM program), 1), (SELECT COUNT(*) > 0 FROM program));

SELECT setval(pg_get_serial_sequence('subject', 'id'), COALESCE((SELECT MAX(id) FROM subject), 1), (SELECT COUNT(*) > 0 FROM subject));

SELECT setval(pg_get_serial_sequence('olympiad', 'id'), COALESCE((SELECT MAX(id) FROM olympiad), 1), (SELECT COUNT(*) > 0 FROM olympiad));

SELECT setval(pg_get_serial_sequence('subject_olympiad', 'id'), COALESCE((SELECT MAX(id) FROM subject_olympiad), 1), (SELECT COUNT(*) > 0 FROM subject_olympiad));

SELECT setval(pg_get_serial_sequence('stage', 'stage_id'), COALESCE((SELECT MAX(stage_id) FROM stage), 1), (SELECT COUNT(*) > 0 FROM stage));

SELECT setval(pg_get_serial_sequence('benefit', 'id'), COALESCE((SELECT MAX(id) FROM benefit), 1), (SELECT COUNT(*) > 0 FROM benefit));

COMMIT;
